        targetMatrix.add(new Triple());
    }
    int[] number = new int[colNumber];
    for(int i = 0; i < colNumber; i ++) {
        number[i] = 0;
    }
    for(Triple triple : rawMatrix) {
        number[triple.getCol()] ++;
    }
    int[] position = new int[colNumber];
    position[0] = 0;
