        int col = triple.getCol();
        int row = triple.getRow();
        targetMatrix.get(position[col]).setRow(col);
        targetMatrix.get(position[col]).setCol(row);
        targetMatrix.get(position[col]).setNumber(triple.getNumber());
        position[col] ++;
    }
    System.out.println("\n转置后的矩阵三元组如下：");
    for(Triple triple : targetMatrix) {
        System.out.println(triple.toString());
    }
    System.out.println();
